import React from 'react';
import './Process.css';

const STEPS = [
  {
    num: '01',
    title: 'Discovery & Alignment',
    desc: 'We align on your goals, user needs, and technical constraints to define a clear, execution-ready roadmap.',
    dark: true,
  },
  {
    num: '02',
    title: 'Planning & Strategy',
    desc: 'Technical architecture planning, resource allocation, timeline creation, and risk assessment to ensure project success.',
    dark: false,
  },
  {
    num: '03',
    title: 'Design & Prototyping',
    desc: 'User flows, wireframes, and interactive prototypes that validate assumptions before development begins.',
    dark: true,
  },
  {
    num: '04',
    title: 'Development & QA',
    desc: 'Iterative development with continuous testing, security reviews, and transparent progress updates.',
    dark: false,
  },
  {
    num: '05',
    title: 'Launch & Support',
    desc: 'Deployment, monitoring, performance optimization, and ongoing enhancements as your product evolves.',
    dark: true,
  },
];

export default function Process() {
  return (
    <section className="py-section" id="process">
      <div className="container mb-12">
        <h2 className="font-display text-3xl font-semibold lg:text-4xl">Development Process</h2>
        <p className="text-xl lg:text-2xl mt-2 text-gray-600">
          Two distinct experiences optimized for your device.
        </p>
      </div>

      {/* 💻 LAPTOP/DESKTOP VIEW: The "Old" Industrial Block Design */}
      <div className="hidden lg:block border-y border-black bg-white">
        <div className="container-fluid px-0">
          <div className="flex w-full">
            {STEPS.map((step) => (
              <div
                key={step.num}
                className={`flex-1 flex flex-col p-10 border-r last:border-r-0 border-black min-h-[400px] ${step.dark ? 'bg-black text-white' : 'bg-gray-900 text-white'
                  }`}
              >
                <span className="font-mono font-bold text-6xl opacity-20 mb-8" style={{ color: 'var(--color-primary-500)' }}>
                  {step.num}
                </span>
                <h3 className="font-display text-2xl font-bold mb-6">
                  {step.title}
                </h3>
                <p className="text-base text-gray-400 leading-relaxed">
                  {step.desc}
                </p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* 📱 MOBILE/TABLET VIEW: The "New" Modern Timeline Design */}
      <div className="lg:hidden container">
        <div className="process-mobile-timeline">
          {STEPS.map((step, i) => (
            <div key={step.num} className="mobile-step-card">
              <div className="mobile-step-card__side">
                <div className="mobile-step-card__circle">{step.num}</div>
                {i !== STEPS.length - 1 && <div className="mobile-step-card__line" />}
              </div>
              <div className="mobile-step-card__body">
                <h3 className="font-display text-xl font-bold text-black">{step.title}</h3>
                <p className="text-gray-600 mt-2 leading-relaxed">{step.desc}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
